  std::set<int> values{1, 2, 4, 8};
  auto i = values.begin();
  std::advance(i, 2);
  if (*i != 4)
    return 1;
  std::advance(i, -1);
  std::advance(i, 0);
  return *i == 2 ? 0 : 2;
}

