int main() {
  std::set<int> values;
  if (!std::empty(values) || std::begin(values) != std::end(values))
    return 1;
  values.insert(2);
  values.insert(7);
  auto iterator = std::begin(values);
  auto finish = std::end(values);
  return !std::empty(values) && std::size(values) == 2 && *iterator++ == 2 &&
         *iterator++ == 7 && iterator == finish ? 0 : 2;
}

