  if (first != values.begin() || first->first != 0 || first->second != 0)
    return 1;
  first->second = 17;
  auto duplicate = values.emplace_hint(values.cend());
  return duplicate == first && duplicate->second == 17 && values.size() == 3 ? 0 : 2;
